    import numpy as np
    from scipy import stats as sp_stats
    anomalies = []
    skip_cols = ['order_id']
    cap = 25
    for col in num_cols:
        if col in skip_cols:
            continue
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0
        if s.min() < 0:
            shift = -s.min() + 1
        if abs(skew) > 2:
            vals = np.log1p(s + shift)
        else:
            vals = s.copy()
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (vals < lo3) | (vals > hi3)
        frac = mask.sum() / len(vals)
        if frac > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": f"{float(s.quantile(0.25)):.3g} to {float(s.quantile(0.75)):.3g}",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme-value flagging skipped"
            })
            continue
        flagged = df.loc[mask[mask].index]
        for idx, row in flagged.iterrows():
            if len(anomalies) >= cap:
                break
            raw_val = row[col]
            if abs(skew) > 2:
                lo_orig = float(np.expm1(lo3) - shift)
                hi_orig = float(np.expm1(hi3) - shift)
            else:
                lo_orig = float(lo3)
                hi_orig = float(hi3)
            v_t = np.log1p(raw_val + shift) if abs(skew) > 2 else raw_val
            if v_t > hi5 or v_t < lo5:
                sev = "critical"
            elif v_t > hi4 or v_t < lo4:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": float(raw_val),
                "expected_range": f"{lo_orig:.3g} to {hi_orig:.3g}",
                "severity": sev,
                "explanation": f"{col} value {float(raw_val):.3g} lies outside expected range {lo_orig:.3g} to {hi_orig:.3g}"
            })
    result["anomalies"] = anomalies
except Exception:
