    import numpy as np
    from scipy import stats as sp_stats
    anomalies = []
    skip_cols = set()
    for col in num_cols:
        s = df[col].dropna()
        if s.nunique() < 5:
            skip_cols.add(col)
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = -s.min() if s.min() < 0 else 0
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3*iqr, q3 + 3*iqr
        flagged = s_t[(s_t < lo) | (s_t > hi)]
        if len(flagged) / len(s_t) > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": "heavy-tailed distribution",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme values are natural for this distribution"
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo) - shift)
            hi_orig = float(np.expm1(hi) - shift)
        else:
            lo_orig, hi_orig = float(lo), float(hi)
        exp_range = f"[{lo_orig:.2f}, {hi_orig:.2f}]"
        for idx in flagged.index:
            raw_val = float(df.loc[idx, col])
            t_val = float(s_t[idx])
            if t_val > q3 + 5*iqr or t_val < q1 - 5*iqr:
                sev = "critical"
            elif t_val > q3 + 4*iqr or t_val < q1 - 4*iqr:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": raw_val,
                "expected_range": exp_range, "severity": sev,
                "explanation": f"{col} value {raw_val} lies outside expected range {exp_range}"
            })
            if len(anomalies) >= 25:
                break
        if len(anomalies) >= 25:
            break
    result['anomalies'] = anomalies
except Exception:
    pass

