        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        Q1 = s_t.quantile(0.25)
        Q3 = s_t.quantile(0.75)
        IQR = Q3 - Q1
        lo3 = Q1 - 3 * IQR
        hi3 = Q3 + 3 * IQR
        lo4 = Q1 - 4 * IQR
        hi4 = Q3 + 4 * IQR
        lo5 = Q1 - 5 * IQR
        hi5 = Q3 + 5 * IQR
        mask = (s_t < lo3) | (s_t > hi3)
        if mask.sum() / len(s_t) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are natural, not flagged individually'
            })
            continue
        if abs(skew) > 2:
            lo3_orig = float(np.expm1(lo3) - shift)
            hi3_orig = float(np.expm1(hi3) - shift)
            lo4_orig = float(np.expm1(lo4) - shift)
            hi4_orig = float(np.expm1(hi4) - shift)
            lo5_orig = float(np.expm1(lo5) - shift)
            hi5_orig = float(np.expm1(hi5) - shift)
        else:
            lo3_orig, hi3_orig = float(lo3), float(hi3)
            lo4_orig, hi4_orig = float(lo4), float(hi4)
            lo5_orig, hi5_orig = float(lo5), float(hi5)
        flagged = s_t[mask]
        for idx, tv in flagged.items():
            orig_val = float(df.loc[idx, col])
            if tv < lo5 or tv > hi5:
                sev = 'critical'
            elif tv < lo4 or tv > hi4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col,
                'row_index': int(idx),
                'value': orig_val,
                'expected_range': f'[{lo3_orig:.4g}, {hi3_orig:.4g}]',
                'severity': sev,
                'explanation': f'{col} value {orig_val} lies outside expected range [{lo3_orig:.4g}, {hi3_orig:.4g}]'
