try:
    import numpy as np
    from scipy import stats

    df['order_date'] = pd.to_datetime(df['order_date'])
    metrics = ['revenue', 'units', 'discount', 'marketing_spend']
    seg_cols = ['segment', 'region']

    # EDA
    eda = {}
    for col in metrics:
        s = df[col].dropna()
        eda[col] = {
            "mean": float(s.mean()), "std": float(s.std()),
            "min": float(s.min()), "max": float(s.max()),
            "median": float(s.median()), "count": int(s.count())
        }
    result['eda_summary'] = eda
except Exception as e:
    result['assumptions'].append(f"EDA error: {e}")

try:
    # Correlations
    num_df = df[metrics].dropna()
    corr_dict = {}
    for i, c1 in enumerate(metrics):
        for c2 in metrics[i+1:]:
            r = num_df[c1].corr(num_df[c2])
            if abs(r) >= 0.2:
                corr_dict[f"{c1}__{c2}"] = round(float(r), 4)
    result['correlations'] = corr_dict
except Exception as e:
    result['assumptions'].append(f"Correlation error: {e}")

try:
    # Segmentation
    segs = []
    for seg in seg_cols:
        top10 = df[seg].value_counts().head(10).index.tolist()
        sub = df[df[seg].isin(top10)]
        for metric in metrics:
            grp = sub.groupby(seg)[metric].mean()
            segs.append({
                "segment_column": seg, "metric_column": metric,
                "aggregation": "mean", "label": None,
                "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in grp.items()]
            })
        cnt = sub.groupby(seg)[metrics[0]].count()
        segs.append({
            "segment_column": seg, "metric_column": metrics[0],
            "aggregation": "count", "label": None,
            "results": [{"name": str(k), "value": int(v)} for k, v in cnt.items()]
        })
    # Joint breakdown segment x region
    if len(seg_cols) >= 2:
        c1, c2 = seg_cols[0], seg_cols[1]
        joint = df.groupby([c1, c2])['revenue'].mean()
        joint_results = [{"name": f"{a}|{b}", "value": round(float(v), 4)} for (a, b), v in joint.items()]
        segs.append({
            "segment_column": f"{c1}|{c2}", "metric_column": "revenue",
            "aggregation": "mean", "label": None,
            "results": joint_results
        })
    result['segments'] = segs
except Exception as e:
    result['assumptions'].append(f"Segmentation error: {e}")

try:
    # Anomalies
    anomalies = []
    id_like = ['order_id']
    skip_cols = set(id_like)
    for col in metrics:
        if col in skip_cols:
            continue
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        Q1, Q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        IQR = Q3 - Q1
        lo_t, hi_t = Q1 - 3 * IQR, Q3 + 3 * IQR
        mask = (s_t < lo_t) | (s_t > hi_t)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": "heavy-tailed distribution",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme values are natural for this distribution"
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_t) - shift)
            hi_orig = float(np.expm1(hi_t) - shift)
        else:
            lo_orig = float(lo_t)
            hi_orig = float(hi_t)
        exp_range = f"[{lo_orig:.4g}, {hi_orig:.4g}]"
        flagged = s[mask.reindex(s.index, fill_value=False)]
        lo5, hi5 = Q1 - 5 * IQR, Q3 + 5 * IQR
        lo4, hi4 = Q1 - 4 * IQR, Q3 + 4 * IQR
        for idx, val in flagged.items():
            if len(anomalies) >= 25:
                break
            v_t = s_t.loc[idx]
            if v_t < lo5 or v_t > hi5:
                sev = "critical"
            elif v_t < lo4 or v_t > hi4:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": float(val),
                "expected_range": exp_range, "severity": sev,
                "explanation": f"{col} value {float(val):.4g} lies outside expected range {exp_range}"
            })
    result['anomalies'] = anomalies
except Exception as e:
    result['assumptions'].append(f"Anomaly error: {e}")

try:
    # Trends - 7d rolling and MoM for non-target-pair metrics
    df_t = df.set_index('order_date').sort_index()
    trends = []
    for col in metrics:
        roll = df_t[col].resample('7D').mean()
        if len(roll) >= 2:
            pct = float((roll.iloc[-1] - roll.iloc[0]) / roll.iloc[0] * 100) if roll.iloc[0] != 0 else 0.0
            direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
            trends.append({"column": col, "period": "7d_rolling", "direction": direction,
                           "pct_change": round(pct, 4), "segment": None})
