try:
    import numpy as np
    from scipy import stats

    df['month'] = pd.to_datetime(df['month'])
    numeric_cols = ['earned_premium', 'claim_count', 'claim_amount']
    seg_cols = ['line', 'region']

    # EDA
    eda = {}
    for col in numeric_cols:
        s = df[col].dropna()
        eda[col] = {
            "mean": float(s.mean()), "std": float(s.std()),
            "min": float(s.min()), "max": float(s.max()),
            "median": float(s.median()), "count": int(s.count())
        }
    result['eda_summary'] = eda
except Exception as e:
    result['assumptions'].append(f"EDA error: {e}")

try:
    # Correlations (beyond target pairs)
    corr_pairs = {}
    all_num = df[numeric_cols].dropna()
    for i, c1 in enumerate(numeric_cols):
        for c2 in numeric_cols[i+1:]:
            r, _ = stats.pearsonr(all_num[c1], all_num[c2])
            if abs(r) >= 0.2:
                corr_pairs[f"{c1}__{c2}"] = round(float(r), 4)
    result['correlations'] = corr_pairs
except Exception as e:
    result['assumptions'].append(f"Correlation error: {e}")

try:
    # Segmentation
    segs = []
    for seg in seg_cols:
        top10 = df[seg].value_counts().head(10).index.tolist()
        sub = df[df[seg].isin(top10)]
        for metric in numeric_cols:
            agg_res = sub.groupby(seg)[metric].sum()
            segs.append({
                "segment_column": seg, "metric_column": metric,
                "aggregation": "sum", "label": None,
                "results": [{"name": str(k), "value": float(v)} for k, v in agg_res.items()]
            })
        # Loss ratio per segment
        lr = sub.groupby(seg).apply(lambda x: x['claim_amount'].sum() / x['earned_premium'].sum() if x['earned_premium'].sum() > 0 else float('nan'))
        segs.append({
            "segment_column": seg, "metric_column": "claim_amount",
            "aggregation": "ratio", "label": "loss_ratio",
            "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in lr.items() if not np.isnan(v)]
        })
    # Joint breakdown line|region
    if len(seg_cols) >= 2:
        joint = df.groupby([seg_cols[0], seg_cols[1]])['earned_premium'].sum().reset_index()
        joint['name'] = joint[seg_cols[0]].astype(str) + '|' + joint[seg_cols[1]].astype(str)
        segs.append({
            "segment_column": f"{seg_cols[0]}|{seg_cols[1]}", "metric_column": "earned_premium",
            "aggregation": "sum", "label": None,
            "results": [{"name": r['name'], "value": float(r['earned_premium'])} for _, r in joint.iterrows()]
        })
    result['segments'] = segs
except Exception as e:
    result['assumptions'].append(f"Segmentation error: {e}")

try:
    # Trends: 7d_rolling not applicable (monthly data); MoM for non-target metrics skipped (handled externally)
    # YoY: only one year of data, skip
    # Additional: claim_count MoM per line (supplemental)
    df_m = df.copy()
    df_m['ym'] = df_m['month'].dt.to_period('M')
    trends = []
    for metric in numeric_cols:
        monthly = df_m.groupby('ym')[metric].sum().sort_index()
        if len(monthly) >= 2:
            pct = float((monthly.iloc[-1] - monthly.iloc[-2]) / monthly.iloc[-2] * 100) if monthly.iloc[-2] != 0 else 0.0
            direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
            trends.append({"column": metric, "period": "MoM", "direction": direction, "pct_change": round(pct, 4), "segment": None})
