        vals = np.log1p(s + shift) if abs(skew) > 2 else s
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo_log, hi_log = q1 - 3 * iqr, q3 + 3 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        mask = (vals < lo_log) | (vals > hi_log)
        frac = mask.sum() / len(vals)
        if frac > 0.05:
            if abs(skew) > 2:
                lo_orig = float(np.expm1(lo_log) - shift)
                hi_orig = float(np.expm1(hi_log) - shift)
            else:
                lo_orig, hi_orig = float(lo_log), float(hi_log)
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": f"[{lo_orig:.2f}, {hi_orig:.2f}]",
