                "explanation": f"{col} is heavy-tailed; extreme-value flagging skipped"
            })
            skip_cols.add(col)
            continue
        flagged = df.index[mask]
        for idx in flagged:
            if len(anomalies) >= total_cap:
                break
            raw_val = df.loc[idx, col]
            log_val = vals.loc[idx]
            if log_val > hi5 or log_val < lo5:
                sev = "critical"
            elif log_val > hi4 or log_val < lo4:
                sev = "high"
            else:
                sev = "medium"
            if abs(skew) > 2:
                lo_orig = float(np.expm1(lo_log) - shift)
                hi_orig = float(np.expm1(hi_log) - shift)
            else:
                lo_orig, hi_orig = float(lo_log), float(hi_log)
            exp_range = f"[{lo_orig:.2f}, {hi_orig:.2f}]"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": float(raw_val),
                "expected_range": exp_range, "severity": sev,
                "explanation": f"{col} value {raw_val} lies outside expected range {exp_range}"
            })
        if len(anomalies) >= total_cap:
            break
    result['anomalies'] = anomalies
except Exception as e:
    result['assumptions'].append(f"Anomaly error: {e}")

