result['builtin'] = []
_targets, _segs, _date, _hints = ['left', 'tenure_months', 'salary', 'performance_score'], ['department', 'employee_name'], 'hire_date', {'left': ['mean', [], None], 'tenure_months': ['mean', [], None], 'salary': ['mean', [], None]}
