    df['hire_date_parsed'] = pd.to_datetime(df['hire_date'], errors='coerce')
    df['hire_ym'] = df['hire_date_parsed'].dt.to_period('M')
    for metric in ['left', 'tenure_months', 'salary', 'performance_score']:
        monthly = df.groupby('hire_ym')[metric].mean().sort_index()
        if len(monthly) < 2:
            continue
        pct = float((monthly.iloc[-1] - monthly.iloc[-2]) / monthly.iloc[-2] * 100) if monthly.iloc[-2] != 0 else 0.0
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            'column': metric, 'period': 'MoM', 'direction': direction,
            'pct_change': round(pct, 4), 'segment': None
        })
    monthly_hires = df.groupby('hire_ym')['employee_id'].count().sort_index()
    if len(monthly_hires) >= 2:
        pct_h = float((monthly_hires.iloc[-1] - monthly_hires.iloc[-2]) / monthly_hires.iloc[-2] * 100) if monthly_hires.iloc[-2] != 0 else 0.0
        dir_h = 'up' if pct_h > 1 else ('down' if pct_h < -1 else 'flat')
        result['trends'].append({
            'column': 'employee_id', 'period': 'MoM', 'direction': dir_h,
            'pct_change': round(pct_h, 4), 'segment': 'hire_count'
        })
except Exception as e:
    result['assumptions'].append(f"Trend partial failure: {e}")

try:
    import numpy as np
    df['hire_date_parsed'] = pd.to_datetime(df['hire_date'], errors='coerce')
    df['hire_ym'] = df['hire_date_parsed'].dt.to_period('M')
    monthly_sal = df.groupby('hire_ym')['salary'].mean().sort_index().dropna()
    if len(monthly_sal) >= 3:
        x = np.arange(len(monthly_sal))
        y = monthly_sal.values
        coeffs = np.polyfit(x, y, 1)
        last_period = monthly_sal.index[-1]
        next_period = str(last_period + 1)
        next_val = float(np.polyval(coeffs, len(monthly_sal)))
        result['forecast_points'].append({'period': next_period, 'value': round(next_val, 2)})
        next2 = str(last_period + 2)
        next2_val = float(np.polyval(coeffs, len(monthly_sal) + 1))
        result['forecast_points'].append({'period': next2, 'value': round(next2_val, 2)})
except Exception as e:
    result['assumptions'].append(f"Forecast partial failure: {e}")

result['assumptions'].append("left column treated as binary attrition flag; mean = attrition rate.")
result['assumptions'].append("Trends computed on hire_date month groupings (cohort-based, not calendar event).")
result['assumptions'].append("Pearson r used for correlations; linear association only, not causation.")
result['assumptions'].append("Anomaly IQR boundaries use 3x multiplier; log1p applied for skewed columns.")

