            'median': float(s.median()), 'count': int(s.count())
        }
except Exception as e:
    result['assumptions'].append(f"EDA partial failure: {e}")

try:
    import numpy as np
    from scipy import stats
    numeric_df = df[num_cols].dropna()
    cols = numeric_df.columns.tolist()
    for i, c1 in enumerate(cols):
        for c2 in cols[i+1:]:
            pair = numeric_df[[c1, c2]].dropna()
            if len(pair) < 10:
                continue
            r, _ = stats.pearsonr(pair[c1], pair[c2])
            if abs(r) >= 0.2:
                result['correlations'][f"{c1}__{c2}"] = round(float(r), 4)
except Exception as e:
