try:
    seg_col = 'department'
    top_depts = df[seg_col].value_counts().head(10).index.tolist()
    sub = df[df[seg_col].isin(top_depts)]
    for metric in ['left', 'tenure_months', 'salary', 'performance_score']:
        agg = 'mean' if metric != 'left' else 'mean'
        grp = sub.groupby(seg_col)[metric].mean()
        result['segments'].append({
            'segment_column': seg_col, 'metric_column': metric,
            'aggregation': 'mean', 'label': None,
            'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in grp.items()]
        })
    attrition = sub.groupby(seg_col)['left'].mean()
    result['segments'].append({
        'segment_column': seg_col, 'metric_column': 'left',
        'aggregation': 'ratio', 'label': 'attrition_rate',
        'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in attrition.items()]
    })
    count_grp = sub.groupby(seg_col)['left'].count()
    result['segments'].append({
        'segment_column': seg_col, 'metric_column': 'left',
        'aggregation': 'count', 'label': None,
        'results': [{'name': str(k), 'value': float(v)} for k, v in count_grp.items()]
    })
except Exception as e:
    result['assumptions'].append(f"Segmentation partial failure: {e}")

try:
    import numpy as np
    from scipy import stats as sp_stats
    anomaly_records = []
    for col in num_cols:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = -s.min() if s.min() < 0 else 0
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3 * iqr, q3 + 3 * iqr
        flagged = s_t[(s_t < lo) | (s_t > hi)]
        if len(flagged) / len(s_t) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f"{col} is heavy-tailed; extreme values are natural, not flagged individually."
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo) - shift)
            hi_orig = float(np.expm1(hi) - shift)
        else:
            lo_orig, hi_orig = float(lo), float(hi)
        exp_range = f"[{lo_orig:.2f}, {hi_orig:.2f}]"
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        for idx in flagged.index:
            val_t = s_t[idx]
            val_orig = float(df.loc[idx, col])
            if val_t > hi5 or val_t < lo5:
                sev = 'critical'
            elif val_t > hi4 or val_t < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': val_orig,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f"{col} value {val_orig} lies outside expected range {exp_range}."
            })
    anomaly_records = anomaly_records[:25]
    result['anomalies'].extend(anomaly_records)
except Exception as e:
    result['assumptions'].append(f"Anomaly partial failure: {e}")

