            seg_res.append({'name': str(plan), 'value': round(float(grp[metric].sum()), 2)})
        seg_res.sort(key=lambda x: x['value'], reverse=True)
        result['segments'].append({
            'segment_column': 'plan', 'metric_column': metric,
            'aggregation': 'sum', 'label': None, 'results': seg_res
        })
