        flagged_idx = df[col].dropna().index[mask]
        for idx in flagged_idx[:max(0, 25 - total_anomalies)]:
            val = float(df.loc[idx, col])
            s_val = float(np.log1p(val + shift)) if abs(skew) > 2 else val
