        s = df[col].dropna()
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        Q1, Q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        IQR = Q3 - Q1
        lo, hi = Q1 - 3*IQR, Q3 + 3*IQR
        flagged = df[col].dropna()
        s_t_full = np.log1p(flagged + shift) if abs(skew) > 2 else flagged
        mask = (s_t_full < lo) | (s_t_full > hi)
        pct = mask.sum() / len(flagged)
        if pct > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are natural, not flagged'
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo) - shift)
            hi_orig = float(np.expm1(hi) - shift)
        else:
            lo_orig, hi_orig = float(lo), float(hi)
        exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
        flagged_idx = df[col].dropna().index[mask]
        for idx in flagged_idx[:max(0, 25 - total_anomalies)]:
            val = float(df.loc[idx, col])
            s_val = float(np.log1p(val + shift)) if abs(skew) > 2 else val
            if s_val > Q3 + 5*IQR or s_val < Q1 - 5*IQR:
                sev = 'critical'
            elif s_val > Q3 + 4*IQR or s_val < Q1 - 4*IQR:
                sev = 'high'
            else:
                sev = 'medium'
            result['anomalies'].append({
                'column': col, 'row_index': int(idx), 'value': val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {val} lies outside expected range {exp_range}'
            })
            total_anomalies += 1
except Exception:
    pass

