            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                'column': col, 'period': 'MoM', 'direction': direction,
                'pct_change': pct, 'segment': None
            })
except Exception:
    pass

# Forecasting (simple linear extrapolation on mrr)
try:
    monthly_mrr = df.groupby('month').apply(
        lambda g: g.groupby('account_id').last()['mrr'].sum()
    ).reset_index()
    monthly_mrr.columns = ['month', 'mrr']
    monthly_mrr = monthly_mrr.sort_values('month')
    if len(monthly_mrr) >= 3:
        x = np.arange(len(monthly_mrr))
        y = monthly_mrr['mrr'].values
        slope, intercept, r, p, se = stats.linregress(x, y)
        last_month = monthly_mrr['month'].iloc[-1]
