    import numpy as np
    from scipy import stats as sp_stats
    anomaly_records = []
    skip_cols = set()
    for col in ['temperature', 'vibration']:
        s = df[col].dropna()
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = -s.min() if s.min() < 0 else 0
            vals = np.log1p(s + shift)
            log_transformed = True
        else:
            vals = s.copy()
            log_transformed = False
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3 * iqr, q3 + 3 * iqr
        mask = (vals < lo) | (vals > hi)
        if mask.mean() > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging suppressed'
            })
            skip_cols.add(col)
            continue
        flagged = s[mask.values]
        if log_transformed:
            shift_val = -s.min() if s.min() < 0 else 0
            orig_lo = float(np.expm1(lo) - shift_val)
            orig_hi = float(np.expm1(hi) - shift_val)
        else:
            orig_lo, orig_hi = float(lo), float(hi)
        exp_range = f'[{orig_lo:.3f}, {orig_hi:.3f}]'
        for idx, val in flagged.items():
            raw_val = float(s.loc[idx])
            log_val = float(vals.loc[idx]) if log_transformed else raw_val
            if log_val > q3 + 5 * iqr or log_val < q1 - 5 * iqr:
                sev = 'critical'
            elif log_val > q3 + 4 * iqr or log_val < q1 - 4 * iqr:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': exp_range, 'severity': sev,
