try:
    import numpy as np
    from scipy import stats as sp_stats
    anomaly_cols = ['distance_km', 'weight_kg', 'delivery_days', 'cost']
    all_anomalies = []
    for col in anomaly_cols:
        s = df[col].dropna()
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min() + 1)
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3 * iqr, q3 + 3 * iqr
        mask = (s_t < lo) | (s_t > hi)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            all_anomalies.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are natural, not flagged individually'
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo) - shift)
            hi_orig = float(np.expm1(hi) - shift)
        else:
            lo_orig, hi_orig = float(lo), float(hi)
        exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
        flagged = s_t[mask]
        for idx in flagged.index:
            raw_val = float(df.loc[idx, col])
            t_val = float(s_t.loc[idx])
            dist_hi = (t_val - q3) / iqr if t_val > q3 else 0
            dist_lo = (q1 - t_val) / iqr if t_val < q1 else 0
            dist = max(dist_hi, dist_lo)
            if dist > 5:
                sev = 'critical'
            elif dist > 4:
                sev = 'high'
            else:
                sev = 'medium'
            all_anomalies.append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {raw_val} lies outside expected range {exp_range}'
            })
    all_anomalies_sorted = sorted(
        [a for a in all_anomalies if a['row_index'] is not None],
        key=lambda x: ['medium', 'high', 'critical'].index(x['severity']) if x['severity'] in ['medium', 'high', 'critical'] else -1,
        reverse=True
    )[:25]
