try:
    import numpy as np
    df['_date'] = pd.to_datetime(df['ship_date'])
    df['_ym'] = df['_date'].dt.to_period('M')
    monthly_cost = df.groupby('_ym')['cost'].sum().sort_index()
    if len(monthly_cost) >= 3:
        x = np.arange(len(monthly_cost))
        y = monthly_cost.values
        slope, intercept = np.polyfit(x, y, 1)
        next_x = len(monthly_cost)
        next_period = str(monthly_cost.index[-1] + 1)
        forecast_val = float(slope * next_x + intercept)
        result['forecast_points'].append({'period': next_period, 'value': round(forecast_val, 2)})
        next2_period = str(monthly_cost.index[-1] + 2)
        forecast_val2 = float(slope * (next_x + 1) + intercept)
        result['forecast_points'].append({'period': next2_period, 'value': round(forecast_val2, 2)})
except Exception:
    pass

